import {portfolios,allocations,payment,analyze,simulate,schedule,quantile,breakEven,mortgageYield} from './engine.mjs';
const $=id=>document.getElementById(id),money=(x,sign=false)=>!Number.isFinite(x)?'Not applicable':(sign&&x>0?'+':'')+new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(x),short=x=>Math.abs(x)>=1e6?'$'+(x/1e6).toFixed(1)+'m':'$'+Math.round(x/1000)+'k',pct=x=>Number.isFinite(x)?(x*100).toFixed(1)+'%':'Not applicable';
const color=['#c0785e','#a88b79','#8270b6','#487f9a','#1778b8','#658794','#69817e'];
let history=[],result,c,currentScenario='base',hasEdited=false,chartCache=null;
$('portfolio').innerHTML=Object.entries(portfolios).map(([id,p])=>`<option value="${id}">${p.name}</option>`).join('');
function read(){const n=id=>Number($(id).value),rate=id=>n(id)/100;const ids=['balance','rate','term','extra','lump','cash','reserve','mu','sigma','fee','dividendYield','inflation','cashReturn','incomeTax','gainsTax','divTax','withdrawTax','standard','otherDed','eligible','room'];for(const id of ids){if(!$(id).checkValidity()||!Number.isFinite(n(id))||$(id).value==='')throw new Error('Please enter a valid '+$(id).labels[0].textContent.toLowerCase()+'.');}if($('mortgageType').value!=='fixed')throw new Error('This version supports fixed-rate mortgages. Adjustable rates need a reset schedule and payment recalculation before a trustworthy comparison.');let config={balance:n('balance'),rate:rate('rate'),term:n('term'),extra:n('extra'),lump:n('lump'),cash:n('cash'),reserve:n('reserve'),portfolio:$('portfolio').value,horizon:n('horizon'),account:$('account').value,mu:rate('mu'),sigma:rate('sigma'),fee:rate('fee'),dividendYield:rate('dividendYield'),inflation:rate('inflation'),cashReturn:rate('cashReturn'),incomeTax:rate('incomeTax'),gainsTax:rate('gainsTax'),divTax:rate('divTax'),withdrawTax:rate('withdrawTax'),standard:n('standard'),otherDed:n('otherDed'),eligible:rate('eligible'),room:n('room'),access:$('access').checked,taxOn:$('taxOn').checked,valuation:$('valuation').value,scenario:currentScenario};
if(config.extra+config.lump<=0)throw new Error('Add a monthly amount or a lump sum to compare your choices.');if(currentScenario==='sale')config.horizon=Math.min(5,config.horizon);if(currentScenario==='retire')config.horizon=Math.max(1,config.horizon-5);if(currentScenario==='inflation')config.inflation=.06;if(currentScenario==='expense')config.expense=30000;return config;}
function metric(label,value,sub,why){return `<div class="metric"><label>${label}</label><div class="number">${value}</div><p class="hint">${sub}</p><details><summary>Why?</summary><p>${why}</p></details></div>`;}
const inflationFactor=year=> $('real').checked?Math.pow(1+c.inflation,year):1;
const show=(x,sign=false)=>money(x/inflationFactor(c.horizon),sign);
const scenarioText={base:'Original horizon and assumptions. Models remain separate; the overview focuses on the conventional probability model.',crash:'Illustrative stress: equity paths start with −35% in year one; the 60/40 mix uses −18.6%, Treasuries +6%, and cash its assumed yield. Later returns follow each model.',lost:'Illustrative stress: first 10 years have their log returns reduced by the assumed baseline return. This is a weak-return period, not a replay of a particular decade.',bull:'Illustrative stress: first five annual returns are increased by 8 percentage points (capped at +100%).',low:'Illustrative stress: every annual total return is reduced by 3 percentage points.',inflation:'Inflation is 6% per year. Nominal mortgage payments and modeled returns remain unchanged. Turn on today’s dollars to inspect purchasing power; this is not an inflation-linked return forecast.',sale:'Comparison ends at year 5, or your original horizon if shorter. The same home value and sale costs cancel between strategies. No replacement mortgage is modeled.',retire:'Comparison ends five years sooner (minimum one year). Qualified retirement access is unchanged; review it in Assumptions.',expense:'A $30,000 expense at the end of year 3 uses cash first, then taxable assets, then qualified retirement assets if enabled. Any unpaid amount appears as negative cash; financing is not modeled.'};
function render(){const f=result.focus,invest=f.summaries[4],mort=f.summaries[0],best=result.rank[0],robust=f.summaries[f.robust],noDiff=f.diffs.every(x=>Math.abs(x)<1);$('decisionTitle').textContent=`Your ${money(c.extra)}/month decision${c.lump?' + '+money(c.lump)+' today':''}`;$('context').textContent=`${hasEdited?'Your inputs':'Sample inputs · edit to match your mortgage'} · ${c.horizon}-year horizon · ${$('account').selectedOptions[0].textContent} · ${$('real').checked?'today’s':'nominal'} dollars`;$('paymentHint').textContent=`Calculated payment: ${money(payment(c.balance,c.rate,c.term*12))}/month, principal & interest only.`;
let warnings='';if(c.cash<c.reserve)warnings+=`<div class="warning">Reserve comes first. ${money(Math.min(c.lump,c.reserve-c.cash))} of the lump sum is held in cash, and monthly extras fill the remaining gap before allocation.</div>`;if(c.portfolio==='stock')warnings+='<div class="warning">Concentrated investments can suffer permanent loss. The wide uncertainty here still cannot represent company failure reliably; confidence is limited.</div>';if(c.portfolio==='global'||c.portfolio==='intl'||c.portfolio==='custom')warnings+='<div class="warning">Historical evidence is unavailable for this selection. Only illustrative models are compared; confidence is limited.</div>';if(c.account!=='taxable')warnings+=`<div class="warning">${money(c.room)} annual contribution room assumed; overflow goes to taxable brokerage. ${c.access?'Qualified access at the horizon is assumed.':'Retirement / HSA assets are excluded from accessible liquidity.'}</div>`;if(f.summaries.some(s=>s.liquid<c.reserve))warnings+='<div class="warning">Some strategies end with median accessible assets below your chosen reserve. Compare the liquid-assets column before committing money to principal or a locked account.</div>';if(c.expense)warnings+='<div class="warning">Unexpected-expense scenario is active. Inspect liquid assets for a possible funding shortfall; negative cash represents an unpaid expense.</div>';
$('hero').innerHTML=`<div class="hero"><div class="eyebrow">HIGHEST EXPECTED WEALTH · CONVENTIONAL MODEL</div><h3>${noDiff?'Your reserve absorbs the extra money':best.name==='Invest'?'Investing has the higher expected outcome':best.name==='Mortgage'?'Mortgage prepayment has the higher expected outcome':best.name+' has the higher expected outcome'}</h3><p>${noDiff?'The money stays in cash until your chosen reserve is funded. Strategy outcomes are currently identical.':`Investing finishes ahead of mortgage prepayment in about <strong>${Math.round(f.win*100)}%</strong> of paths in this model. The median difference is <strong>${show(f.median,true)}</strong> after ${c.horizon} years.`}</p><div class="hero-bottom"><span class="confidence">${result.robust}</span><small>${result.agree} of ${result.views.length} views agree on the direction of the median</small></div></div>${warnings}`;
$('metrics').innerHTML=metric('Modeled chance investing wins',noDiff?'Tie':`About ${Math.round(f.win*100)}%`,'Conventional model · 350 paired paths','Both strategies experience the same market path. This is the share where investing creates more after-tax wealth, not a forecast of real-world odds.')+metric('Median investing advantage',show(f.median,true),`Over ${c.horizon} years`,'The middle paired difference between investing and prepaying. It is not the difference between two independently selected median paths.')+metric('Poor-market difference',show(f.down,true),'10th percentile of paired differences','In roughly 10% of conventional model paths, the investing-minus-mortgage result is below this amount. A negative value favors mortgage. This is not a worst-case floor.')+metric('Break-even investment return',pct(result.breakEven),'Constant nominal total return, before fees','Solved by running both cash-flow strategies until their after-tax ending wealth is equal. It includes fees, account treatment and the horizon. It is a deterministic threshold, not the return a volatile portfolio must average to guarantee a win.')+metric('Mortgage prepayment equivalent',pct(mortgageYield(c)),'Annualized · after modeled deduction effects','The annualized cash-flow return on an illustrative $1,000 principal payment today. It includes avoided payments, remaining principal advantage at the horizon and the reduction in incremental deductions. It assumes this fixed loan and unchanged tax rules; it is not the return on investments made after payoff.')+metric('Extra liquidity if investing',show(invest.liquid-mort.liquid,true),`Median liquid-asset difference at year ${c.horizon}`,'Taxable assets are valued after an estimated gains tax. Home equity and locked retirement assets are excluded. This is a difference of median liquid balances, not a paired median. Market liquidity does not guarantee a stable balance.');
$('strategyTable').innerHTML=`<thead><tr><th>Extra-money allocation</th><th>Expected wealth</th><th>Median wealth</th><th>10th percentile</th><th>Liquid assets</th><th>Mortgage paid off</th></tr></thead><tbody>${f.summaries.map((s,i)=>`<tr class="${i===best.index?'highlight':''}"><td><span class="swatch" style="background:${color[i]}"></span>${s.name}</td><td>${show(s.mean)}</td><td>${show(s.median)}</td><td>${show(s.p10)}</td><td>${show(s.liquid)}</td><td>${s.payoff===null?'After horizon':s.payoff===0?'Today':(s.payoff/12).toFixed(1)+' years'}</td></tr>`).join('')}</tbody>`;
const withoutTax={...c,taxOn:false};const taxlessBreak=breakEven(withoutTax);const taxChange=result.breakEven-taxlessBreak;
$('robustness').innerHTML=`<div class="card"><div class="eyebrow">WHAT COULD REVERSE THE RESULT?</div><h3>${result.robust}</h3><div class="robust-grid"><div><p>${result.agree===result.views.length?'All available views agree on the invest-versus-mortgage median. They still allow different individual outcomes.':'The views disagree. Historical experience and future assumptions point in different directions; inspect the models before choosing.'}</p><p>The constant-return threshold is <strong>${pct(result.breakEven)}</strong>, versus an assumed ${pct(c.mu)} arithmetic expected return. These are different measures; uncertainty and sequence matter.</p><p>Turning off modeled taxes moves the threshold by <strong>${Number.isFinite(taxChange)?(taxChange*100).toFixed(1)+' percentage points':'an undefined amount'}</strong>.</p></div><div><p class="eyebrow">MOST ROBUST · BY 90TH-PERCENTILE REGRET</p><h3>${noDiff?'All allocations tie':robust.name}</h3><p>Smallest 90th-percentile gap to the best choice in each conventional-model future: ${show(f.regrets[f.robust])}. This criterion may differ from the strategy with the highest expected wealth.</p><button class="subtle" data-go="explore">Challenge with scenarios</button></div></div><details><summary>What changes the conclusion?</summary><p>Lower returns, a shorter horizon, higher investment taxes and a higher mortgage rate can favor prepayment. Accessible savings and a preserved reserve can favor liquidity. Inflation reduces purchasing power for all strategies; by itself a common deflator does not change their nominal ranking.</p></details></div>`;
$('scenarioDescription').textContent=scenarioText[currentScenario];renderViews();renderRanges();renderSensitivity();if($('explore').classList.contains('active'))renderLine();$('validation').innerHTML='<p class="positive">Arithmetic checks passed: published mortgage example, closed-form balances, equal-budget conservation, zero-rate loans, capped payoff, lump sums, reserve protection, tax gross-up and deterministic break-even.</p>';}
function renderViews(){ $('modelViews').innerHTML=result.views.map(v=>`<div class="model-row"><div><strong>${v.name}</strong><p class="hint">${v.type} · ${v.paths.length} ${v.type==='Historical evidence'?'overlapping windows':'paths'}</p><details><summary>Assumptions & limits</summary><p class="hint">${v.description}</p><p class="hint">Median investing-minus-mortgage difference: ${show(v.median,true)}. 10th percentile: ${show(v.down,true)}. ${v.type==='Historical evidence'?'Observed frequency is not a future probability.':'Frequency is conditional on this model, not a validated real-world probability.'}</p></details></div><div class="outcome">${Math.round(v.win*100)}%<div class="bar"><span style="width:${v.win*100}%"></span></div><div class="hint">Invest ahead</div></div><div class="range-detail outcome">${show(v.median,true)}<div class="hint">Median gap</div></div></div>`).join('');}
function renderRanges(){const rows=result.focus.summaries,factor=inflationFactor(c.horizon),lo=Math.min(...rows.map(s=>s.p10/factor)),hi=Math.max(...rows.map(s=>s.p90/factor)),range=Math.max(1,hi-lo),x=v=>150+(v/factor-lo)/range*520;let svg=`<svg viewBox="0 0 760 340" role="img" aria-label="10th to 90th percentile ending wealth ranges for all seven strategies"><title>Ending wealth created: 10th–90th percentile ranges with median dots</title>`;for(let k=0;k<=4;k++){const pos=150+k*130;svg+=`<line x1="${pos}" x2="${pos}" y1="12" y2="295" stroke="#e5edf2"/><text class="chart-text" x="${pos}" y="323" text-anchor="middle">${short(lo+k*range/4)}</text>`;}rows.forEach((s,i)=>{let y=30+i*38;svg+=`<text class="chart-text" x="0" y="${y+5}">${s.name}</text><line x1="${x(s.p10)}" x2="${x(s.p90)}" y1="${y}" y2="${y}" stroke="${color[i]}" stroke-width="11" opacity=".3" stroke-linecap="round"/><circle cx="${x(s.median)}" cy="${y}" r="5" fill="${color[i]}"><title>${s.name}: ${show(s.p10)} to ${show(s.p90)}; median ${show(s.median)}</title></circle>`;});$('rangeChart').innerHTML=svg+'</svg>';}
function renderLine(){if(!chartCache){const idx=[0,4,2],paths=result.focus.paths;chartCache=idx.map(i=>paths.map(row=>simulate(c,allocations[i],row,true).series));}const measure=$('chartType').value;let tracks=[];if(measure==='probability'){tracks=[Array.from({length:c.horizon+1},(_,y)=>chartCache[0].filter((s,k)=>chartCache[1][k][y].wealth>s[y].wealth+1).length/chartCache[0].length)];}else tracks=chartCache.map(paths=>Array.from({length:c.horizon+1},(_,y)=>quantile(paths.map(s=>s[y][measure]/inflationFactor(y)),.5)));const lo=Math.min(0,...tracks.flat()),hi=Math.max(1,...tracks.flat())*1.06,x=y=>65+y/c.horizon*610,y=v=>245-(v-lo)/(hi-lo)*220;let svg=`<svg viewBox="0 0 710 300" role="img" aria-label="${measure==='probability'?'Modeled probability investing is ahead':'Median '+measure+' by year'}"><title>${measure==='probability'?'Modeled frequency of investing ahead over time':'Median '+measure+' over time'}</title>`;for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;svg+=`<line x1="65" x2="675" y1="${y(v)}" y2="${y(v)}" stroke="#e5edf2"/><text class="chart-text" x="55" y="${y(v)+5}" text-anchor="end">${measure==='probability'?Math.round(v*100)+'%':short(v)}</text>`;}for(let i=0;i<=4;i++){const yr=Math.round(c.horizon*i/4);svg+=`<text class="chart-text" x="${x(yr)}" y="279" text-anchor="middle">Year ${yr}</text>`;}tracks.forEach((s,k)=>{const col=measure==='probability'?color[4]:[color[0],color[4],color[2]][k];svg+=`<path d="${s.map((v,i)=>(i?'L':'M')+x(i)+','+y(v)).join(' ')}" fill="none" stroke="${col}" stroke-width="3"/>`;s.forEach((v,i)=>svg+=`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="${col}"><title>Year ${i}: ${measure==='probability'?Math.round(v*100)+'%':money(v)}</title></circle>`);});$('lineChart').innerHTML=svg+'</svg>';$('lineTitle').textContent=measure==='wealth'?'Wealth created over time':measure==='liquid'?'Accessible assets over time':'How often does investing finish ahead?';$('lineHint').textContent=measure==='probability'?'Share of paired conventional-model paths at each year; year zero may tie.':'Median at each year · conventional model · lines do not represent one actual path';document.querySelector('.legend').style.display=measure==='probability'?'none':'flex';}
function renderSensitivity(){const rates=[0,.02,.04,.06,.08,.10],horizons=[5,10,c.horizon,20].filter((v,i,a)=>a.indexOf(v)===i).sort((a,b)=>a-b);$('sensitivity').innerHTML=`<div class="table-scroll"><table><thead><tr><th>Annual total return</th>${horizons.map(h=>`<th>${h} years</th>`).join('')}</tr></thead><tbody>${rates.map(r=>`<tr><td>${pct(r)}</td>${horizons.map(h=>{const cfg={...c,horizon:h};const row=Array(h).fill(r),d=simulate(cfg,allocations[4],row).wealth-simulate(cfg,allocations[0],row).wealth;return `<td class="${d>1?'positive':d< -1?'negative':''}">${money(d/($('real').checked?Math.pow(1+c.inflation,h):1),true)}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">Positive = investing ahead. Negative = mortgage ahead. Each column uses the displayed horizon, even if a scenario stops the main comparison earlier.</p>`;}
async function run(){try{const next=read();$('error').textContent='';$('status').textContent='Comparing paired market paths…';$('calculate').disabled=true;await new Promise(r=>requestAnimationFrame(()=>setTimeout(r,10)));c=next;result=analyze(c,history);chartCache=null;render();$('status').textContent='';}catch(e){$('error').textContent=e.message;$('status').textContent='Results need valid inputs. Previous results, if visible, have not been updated.';}finally{$('calculate').disabled=false;}}
function tab(name){document.querySelectorAll('.panel').forEach(el=>el.classList.toggle('active',el.id===name));document.querySelectorAll('[data-tab]').forEach(el=>el.classList.toggle('active',el.dataset.tab===name));if(name==='explore'&&result)renderLine();}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.addEventListener('click',e=>{if(e.target.dataset.go)tab(e.target.dataset.go);});$('inputs').onsubmit=e=>{e.preventDefault();hasEdited=true;run();};$('applyAssumptions').onclick=()=>{hasEdited=true;run();tab('simple');};document.querySelectorAll('input, select').forEach(el=>el.addEventListener('change',()=>{if(!['real','chartType','customMort','customCash'].includes(el.id))$('status').textContent='Inputs changed. Compare again to update the results.';}));$('portfolio').onchange=()=>{const p=portfolios[$('portfolio').value];$('mu').value=(p.mu*100).toFixed(1);$('sigma').value=(p.sigma*100).toFixed(1);$('dividendYield').value=(p.yield*100).toFixed(1);};$('scenarios').onclick=e=>{if(!e.target.dataset.scenario)return;currentScenario=e.target.dataset.scenario;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.toggle('active',b.dataset.scenario===currentScenario));run();};$('real').onchange=()=>{if(result)render();};$('chartType').onchange=()=>{if(result)renderLine();};$('splitButton').onclick=()=>{if(!result)return;const m=Number($('customMort').value),cash=Number($('customCash').value);if(!$('customMort').checkValidity()||!$('customCash').checkValidity()||m+cash>100){$('customResult').textContent='Use allocations from 0–100% that sum to 100% or less.';return;}const a={name:'Your split',mort:m/100,cash:cash/100,invest:1-(m+cash)/100},rows=result.focus.paths.map(r=>simulate(c,a,r));$('customResult').innerHTML=`<p><strong>${m}% mortgage · ${100-m-cash}% invest · ${cash}% cash</strong></p><p>Median wealth: ${show(quantile(rows.map(r=>r.wealth),.5))}. Poor outcome (10th percentile): ${show(quantile(rows.map(r=>r.wealth),.1))}. Median accessible assets: ${show(quantile(rows.map(r=>r.liquid),.5))}.</p>`;};
$('reportButton').onclick=()=>{if(!result)return;const f=result.focus;const lines=['MORTGAGE VS. INVEST — DECISION REPORT','Created '+new Date().toLocaleDateString('en-US'),'Model v1.0 · educational analysis', '',`Extra money: ${money(c.extra)}/month + ${money(c.lump)} today`,`Mortgage: ${money(c.balance)} at ${pct(c.rate)}, ${c.term} years remaining`,`Calculated P&I: ${money(payment(c.balance,c.rate,c.term*12))}/month`,`Investment: ${portfolios[c.portfolio].name}; account: ${c.account}`,`Comparison horizon: ${c.horizon} years; scenario: ${currentScenario}`,`Amounts: ${$('real').checked?'today’s':'nominal'} dollars`, '',`Highest expected wealth: ${result.rank[0].name} (conventional model)`,`Investing ahead: about ${Math.round(f.win*100)}% of conventional model paths`,`Median paired advantage: ${show(f.median,true)}`,`Poor-market paired difference (10th percentile): ${show(f.down,true)}`,`Constant-return break-even: ${pct(result.breakEven)}`,`Mortgage prepayment equivalent: ${pct(mortgageYield(c))} annualized under modeled tax assumptions; note rate ${pct(c.rate)}`,`Median liquidity difference, invest minus mortgage: ${show(f.summaries[4].liquid-f.summaries[0].liquid,true)}`,`Robustness: ${result.robust}`,`Most robust by 90th-percentile regret: ${f.summaries[f.robust].name}`, '', 'SEPARATE MODEL VIEWS',...result.views.map(v=>`${v.name}: ${Math.round(v.win*100)}% invest ahead; median gap ${show(v.median,true)}. ${v.type}. ${v.description}`),'','STRATEGY COMPARISON',...f.summaries.map(s=>`${s.name}: expected ${show(s.mean)}, median ${show(s.median)}, p10 ${show(s.p10)}, liquid ${show(s.liquid)}`),'','ASSUMPTIONS',JSON.stringify(c,null,2),'','VALUES & LIMITS','Wealth created = cash + after-tax investment assets + principal repaid; common existing home equity excluded.','Same household cash flow; freed P&I is redeployed after mortgage payoff. Cash reserve filled first.','Historical frequency is not future probability. Models are illustrative and not calibrated real-world forecasts.','Tax rates and contribution room are user assumptions; verify eligibility. Fixed-rate only. No PMI, recast, refinance, penalties, employer match or tax-law changes.','The largest reversal risks are returns, horizon, taxes, mortgage rate and access to liquidity.','Historical source: https://pages.stern.nyu.edu/adamodar/New_Home_Page/datafile/histretSP.html','Tax reference: https://www.irs.gov/publications/p936'];const blob=new Blob([lines.join('\n')],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mortgage-invest-decision-report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{history=(await (await fetch('./history.json')).json()).rows;await run();}catch(e){$('error').textContent='Historical data could not load. Reload the page to run the comparison.';}
// Browser-agent tools call the same validated inputs and calculator as the page.
const lifecycle=new AbortController();
const concise=()=>result?{inputs:c,model:'Conventional probability model',expectedWealthLeader:result.rank[0].name,investingAheadFrequency:Math.round(result.focus.win*100),medianPairedDifference:Math.round(result.focus.median),poorPairedDifference:Math.round(result.focus.down),constantReturnBreakEven:result.breakEven,mortgageEquivalent:mortgageYield(c),robustness:result.robust,views:result.views.map(v=>({name:v.name,type:v.type,investingAheadFrequency:Math.round(v.win*100),medianPairedDifference:Math.round(v.median)}))}:{error:'No valid analysis is available.'};
if(document.modelContext?.registerTool){const defs=[{name:'read_mortgage_invest_analysis',title:'Read decision analysis',description:'Read the currently calculated inputs and model-conditional results. Does not change inputs.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:input=>{if(input&&Object.keys(input).length)throw new Error('No input properties are accepted.');return concise();}},{name:'configure_and_compare_mortgage_invest',title:'Compare mortgage and investment choices',description:'Update the visible essential calculator inputs and run the validated financial engine. Rates are percentage points (2.99 means 2.99%). Preserves advanced tax and market assumptions unless portfolio is changed, which resets its default return assumptions.',inputSchema:{type:'object',properties:{balance:{type:'number',minimum:1,maximum:10000000},rate:{type:'number',minimum:0,maximum:20},term:{type:'integer',minimum:1,maximum:40},extra:{type:'number',minimum:0,maximum:100000},lump:{type:'number',minimum:0,maximum:10000000},cash:{type:'number',minimum:0,maximum:10000000},reserve:{type:'number',minimum:0,maximum:10000000},horizon:{type:'integer',enum:[5,10,12,15,20,27,30,40]},portfolio:{type:'string',enum:Object.keys(portfolios)},account:{type:'string',enum:['taxable','roth','traditional','hsa']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},async execute(input){if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('An object is required.');const ranges={balance:[1,1e7],rate:[0,20],term:[1,40],extra:[0,1e5],lump:[0,1e7],cash:[0,1e7],reserve:[0,1e7]};const choices={horizon:[5,10,12,15,20,27,30,40],portfolio:Object.keys(portfolios),account:['taxable','roth','traditional','hsa']};for(const [key,value]of Object.entries(input)){if(ranges[key]){if(typeof value!=='number'||!Number.isFinite(value)||value<ranges[key][0]||value>ranges[key][1]||(key==='term'&&!Number.isInteger(value)))throw new Error('Invalid '+key);}else if(choices[key]){if(!choices[key].includes(value))throw new Error('Invalid '+key);}else throw new Error('Unsupported input: '+key);}if(Number(input.extra??$('extra').value)+Number(input.lump??$('lump').value)<=0)throw new Error('A monthly amount or lump sum is required.');if($('mortgageType').value!=='fixed')throw new Error('Only fixed-rate mortgages are supported.');const old=Object.fromEntries([...new Set([...Object.keys(input),'mu','sigma','dividendYield'])].map(k=>[k,$(k).value]));try{for(const[k,v]of Object.entries(input))$(k).value=String(v);if(input.portfolio)$('portfolio').onchange();read();}catch(e){for(const[k,v]of Object.entries(old))$(k).value=v;throw e;}hasEdited=true;await run();if($('error').textContent)throw new Error($('error').textContent);tab('simple');return concise();}}];for(const def of defs){try{await document.modelContext.registerTool(def,{signal:lifecycle.signal});}catch{ /* Optional browser capability; the calculator remains functional. */ }}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
